SELECT table_name,column_name,data_type,numeric_precision,numeric_scale FROM information_schema.columns WHERE table_schema='public' AND (column_name ~* '(amount|price|cost|total|balance|debit|credit|salary|tax|vat|discount|fee|subtotal|paid|due|rate|wage|bonus|deduction|allowance|value|net|gross|tip|charge)') AND data_type IN ('real','double precision','money','integer','bigint','smallint','numeric') ORDER BY data_type,table_name,column_name;
